const response = $input.first().json;
const payload = response.data ?? response;
const reminders = Array.isArray(payload.reminders) ? payload.reminders : [];
const config = $('Nạp cấu hình an toàn').first().json;
const runId = String($execution.id);

if (reminders.length === 0) {
  return [{ json: { skip: true, runId, generatedAt: payload.generatedAt, ...config } }];
}

return reminders.map((reminder) => ({
  json: {
    skip: false,
    runId,
    ...config,
    ...reminder
  }
}));

const item = $json;
const employee = item.employee;
const manager = item.manager;
const course = item.course;
const testRecipientEmail = String(item.testRecipientEmail || '').trim();
const employeeEmail = testRecipientEmail || employee.email;
const managerEmail = manager ? (testRecipientEmail || manager.email || '') : '';
const overdue = item.daysRemaining < 0;
const dueLabel = overdue
  ? `đã quá hạn ${Math.abs(item.daysRemaining)} ngày`
  : item.daysRemaining === 0
    ? 'đến hạn hôm nay'
    : `còn ${item.daysRemaining} ngày`;
const courseLink = course.courseUrl || 'http://localhost:5173/employee/workspace';
const subject = overdue
  ? `[Quá hạn] Khóa học bắt buộc: ${course.title}`
  : `[Nhắc hạn] Khóa học bắt buộc: ${course.title}`;
const employeeHtml = `<p>Chào <strong>${employee.fullName}</strong>,</p><p>Khóa học bắt buộc <strong>${course.title}</strong> ${dueLabel}, nhưng tiến độ hiện tại mới đạt <strong>${item.progressPercent}%</strong>.</p><p>Vui lòng tiếp tục học và hoàn thành đúng hạn.</p><p><a href="${courseLink}">Mở khóa học</a></p><p>Đây là thông báo tự động từ hệ thống Đào tạo nội bộ.</p>`;
const managerHtml = manager
  ? `<p>Chào <strong>${manager.fullName}</strong>,</p><p>Nhân viên <strong>${employee.fullName}</strong> đang có khóa học bắt buộc <strong>${course.title}</strong> ${dueLabel}; tiến độ hiện tại là <strong>${item.progressPercent}%</strong>.</p><p>Vui lòng hỗ trợ đôn đốc nhân viên hoàn thành.</p>`
  : '';
const managerLabel = item.managerSource === 'DEPARTMENT' ? 'Quản lý phòng ban' : 'Quản lý trực tiếp';
const telegramText = `📚 <b>NHẮC TIẾN ĐỘ ĐÀO TẠO</b>\n\nNhân viên: <b>${employee.fullName}</b>\nKhóa học: <b>${course.title}</b>\nTiến độ: <b>${item.progressPercent}%</b>\nHạn: <b>${dueLabel}</b>${manager ? `\n${managerLabel}: <b>${manager.fullName}</b>` : '\n⚠️ Chưa khai báo quản lý cho nhân viên'}`;

return [{ json: {
  ...item,
  employeeEmail,
  managerEmail,
  hasManager: Boolean(manager && managerEmail),
  emailSubject: subject,
  employeeHtml,
  managerHtml,
  telegramText
} }];

const source = $('Soạn nội dung nhắc bằng tiếng Việt').item.json;
const nodeError = (nodeName) => {
  try {
    const output = $(nodeName).item.json;
    return output?.error ? String(output.error.message || output.error) : '';
  } catch (_) {
    return 'Node không chạy hoặc không trả kết quả.';
  }
};

const employeeError = nodeError('Gửi thư nhắc nhân viên');
const managerError = source.hasManager ? nodeError('Thông báo cho quản lý') : '';
const telegramError = nodeError('Thông báo kênh đào tạo');
const employeeNotified = !employeeError;
const managerNotified = source.hasManager && !managerError;
const telegramNotified = !telegramError;
const requiredResults = [employeeNotified, telegramNotified];
if (source.hasManager) requiredResults.push(managerNotified);
const successCount = requiredResults.filter(Boolean).length;
const status = successCount === requiredResults.length
  ? 'SENT'
  : successCount > 0
    ? 'PARTIAL'
    : 'FAILED';
const details = [
  `Nhân viên: ${employeeNotified ? 'đã gửi' : 'lỗi - ' + employeeError}`,
  source.hasManager
    ? `Quản lý: ${managerNotified ? 'đã gửi' : 'lỗi - ' + managerError}`
    : 'Quản lý: bỏ qua vì chưa khai báo',
  `Telegram: ${telegramNotified ? 'đã gửi' : 'lỗi - ' + telegramError}`,
];
return [{ json: {
  apiBaseUrl: source.apiBaseUrl,
  automationSecret: source.automationSecret,
  assignmentId: source.assignmentId,
  runId: source.runId,
  employeeNotified,
  managerNotified,
  telegramNotified,
  status,
  detail: details.join('; ')
} }];
